import sys, os, json, urllib.request, urllib.error
sys.path.insert(0, "/data/scripts")

item = _items[0].get("json", {}) if _items else {}
body = item.get("body", item) if isinstance(item.get("body"), dict) else item
if not isinstance(body, dict):
    body = {}

action = str(body.get("action") or "start").lower()
api = os.environ.get("SITE_CLONE_API_URL") or "http://site-clone-api:7052"
api = api.rstrip("/")

def _http(method, path, payload=None, timeout=30):
    data = None if payload is None else json.dumps(payload).encode()
    req = urllib.request.Request(api + path, data=data, method=method,
                                 headers={"Content-Type": "application/json", "Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read().decode() or "{}")
    except urllib.error.HTTPError as e:
        try:
            err = json.loads(e.read().decode() or "{}")
        except Exception:
            err = {"error": "HTTP %s" % e.code}
        return e.code, err
    except Exception as e:
        return 0, {"ok": False, "error": "site-clone-api unreachable: %s" % type(e).__name__}

if action in ("start", "clone"):
    payload = {
        "url": body.get("url") or "",
        "campaign_id": body.get("campaign_id") or "",
        "job_id": body.get("job_id") or "",
        "options": body.get("options") or body,
        "opsec": body.get("opsec") or {},
        "proxy": body.get("proxy") or {},
    }
    code, data = _http("POST", "/clone", payload)
    if not data.get("ok") and not data.get("job_id"):
        return [{"json": {"ok": False, "error": data.get("error") or "clone start failed", "http": code}}]
    return [{"json": {"ok": True, **{k: data[k] for k in data if k != "ok"}}}]

job_id = str(body.get("job_id") or "")
if action == "cancel":
    if not job_id:
        return [{"json": {"ok": False, "error": "job_id required"}}]
    code, data = _http("POST", "/jobs/%s/cancel" % job_id, {})
    return [{"json": {"ok": bool(data.get("ok")), **data, "http": code}}]

if action == "status":
    if not job_id:
        return [{"json": {"ok": False, "error": "job_id required"}}]
    code, data = _http("GET", "/jobs/%s" % job_id)
    if code == 404:
        return [{"json": {"ok": False, "error": "unknown job"}}]
    # When the clone has finished, push findings into the campaign sketch once.
    if data.get("status") == "done" and not data.get("ingested"):
        sketch = str(body.get("sketch_id") or "")
        analysis = (data.get("analysis") or {})
        if sketch and analysis.get("ok"):
            try:
                import site_clone_ingest
                ingested = site_clone_ingest.ingest_findings(
                    analysis, sketch,
                    campaign_id=str(body.get("campaign_id") or data.get("campaign_id") or ""),
                    job_id=job_id,
                )
                data["ingested"] = ingested
                try:
                    _http("POST", "/jobs/%s/ingested" % job_id, ingested)
                except Exception:
                    pass
            except Exception as e:
                data["ingested"] = {"ok": False, "error": type(e).__name__ + ": " + str(e)[:200]}
    return [{"json": {"ok": True, **{k: data[k] for k in data if k != "ok"}}}]

return [{"json": {"ok": False, "error": "unknown action"}}]
